-- 由 scripts/build_ntpc_waste_history_sql.mjs 自動產生
-- ntpc_waste_mvp_monthly：公噸；末段 ntpc_waste_mvp：公斤（與 import_ntpc_waste_mvp_data / query_chart 一致）
-- 前置：schema_ntpc_waste_mvp_monthly.sql；若曾用舊版公斤欄位請先 migrate_ntpc_monthly_kg_to_tons.sql

BEGIN;


SELECT district,
  ROUND(recycling_tons * 1000)::bigint,
  ROUND(kitchen_tons * 1000)::bigint
FROM public.ntpc_waste_mvp_monthly
WHERE report_month = COALESCE(
  (
    SELECT report_month
    FROM (
      SELECT report_month, SUM(kitchen_tons) AS st
      FROM public.ntpc_waste_mvp_monthly
      GROUP BY report_month
      HAVING SUM(kitchen_tons) > 0
    ) s
    ORDER BY report_month DESC
    LIMIT 1
  ),
  (SELECT MAX(report_month) FROM public.ntpc_waste_mvp_monthly)
)
ON CONFLICT (district) DO UPDATE SET
  recycling_kg = EXCLUDED.recycling_kg,
  kitchen_kg = EXCLUDED.kitchen_kg;

COMMIT;
